class Solution:
    def findSubarrays(self, nums: List[int]) -> bool:
        n = len(nums)
        s = [nums[i] + nums[i + 1] for i in range(n - 1)]
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                if s[i] == s[j]:
                    return True
        return False

