class Solution {
public:
    bool findSubarrays(vector<int>& nums) {
        int n = nums.size();
        vector<long long> s(n - 1);
        for (int i = 0; i < n - 1; i++) s[i] = (long long)nums[i] + nums[i + 1];
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n - 1; j++)
                if (s[i] == s[j]) return true;
        return false;
    }
};

