class Solution {
public:
    bool findSubarrays(vector<int>& nums) {
        unordered_set<long long> seen;
        for (int i = 0; i + 1 < (int)nums.size(); i++) {
            long long s = (long long)nums[i] + nums[i + 1];
            if (!seen.insert(s).second) return true;
        }
        return false;
    }
};

