class Solution {
    public boolean findSubarrays(int[] nums) {
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i + 1 < nums.length; i++) {
            long s = (long) nums[i] + nums[i + 1];
            if (!seen.add(s)) return true;
        }
        return false;
    }
}

